/**
 * The 1.1 vocabulary integration, against the real files.
 *
 * These assert the properties the integration prompt makes non-negotiable: no
 * grammar change, 1.0 carried verbatim, forms generated by the unchanged rule,
 * and the acceptance counts.
 */
import { auditIntegration } from '@core/integrate/audit';
import { ACCEPTED_OVERLAPS, DECISIONS, DUAL_ANALYSIS_PAGO } from '@core/integrate/decisions';
import { NEW_EXAMPLES } from '@core/integrate/examples';
import { integrate, IntegrationError } from '@core/integrate/integrate';
import type { Proposal } from '@core/integrate/proposalTypes';
import { deriveSynonyms } from '@core/integrate/synonyms';
import { sevenForms } from '@core/morphology/sevenForms';
import type { RawLexicon, RawSlots } from '@core/model/raw';
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { fileURLToPath, URL } from 'node:url';
import { beforeAll, describe, expect, it } from 'vitest';
import { freshRawLexicon } from './lexicon';
import { sourcePath } from './sourcePaths';

const BASELINE_SHA = 'adc013cf99b79ec597c8cfcb9aee9f942e520010556ab6b072bcaa9a606608f3';

function repoPath(rel: string): string {
  return fileURLToPath(new URL(`../../${rel}`, import.meta.url));
}

const proposal = JSON.parse(
  readFileSync(repoPath('1.1 upgrade/Liraasa_1_1_Vocabulary_Proposal.json'), 'utf8'),
) as Proposal;

let baseline: RawLexicon;
let result: ReturnType<typeof integrate>;

beforeAll(() => {
  baseline = freshRawLexicon();
  result = integrate(baseline, proposal, {
    version: '1.1',
    builtUtc: '2026-10-16T12:00:00Z',
    baselineSha256: BASELINE_SHA,
    newExamples: NEW_EXAMPLES.map((e) => ({
      liraasa: e.liraasa,
      english: e.english,
      feature: e.feature,
      status: 'NEW',
      source: `1.1 vocabulary examples (${e.domain})`,
    })),
  });
});

describe('the baseline', () => {
  it('is the file the proposal targets', () => {
    const sha = createHash('sha256')
      .update(readFileSync(sourcePath('liraasa_1_0.json')))
      .digest('hex');
    expect(sha).toBe(BASELINE_SHA);
    expect(proposal.source_lexicon_sha256).toBe(BASELINE_SHA);
  });

  it('refuses to integrate against a different baseline', () => {
    expect(() =>
      integrate(baseline, proposal, {
        version: '1.1',
        builtUtc: '2026-10-16T12:00:00Z',
        baselineSha256: 'deadbeef',
      }),
    ).toThrow(IntegrationError);
  });
});

describe('acceptance counts', () => {
  it('reaches 1418 headwords: 407 primal and 1011 compounds', () => {
    const primal = result.lexicon.headwords.filter((h) => h.type === 'Primal');
    expect(result.lexicon.headwords).toHaveLength(1418);
    expect(primal).toHaveLength(407);
    expect(result.lexicon.headwords.length - primal.length).toBe(1011);
  });

  it('adds all 319 proposals and rejects none', () => {
    expect(result.added).toHaveLength(319);
    expect(result.rejected).toEqual([]);
    expect(result.added.filter((a) => a.type === 'Primal')).toHaveLength(21);
    expect(result.added.filter((a) => a.type === 'Compound')).toHaveLength(298);
  });

  it('leaves the function-word count untouched at 149', () => {
    expect(result.lexicon.function_words).toHaveLength(149);
    expect(result.lexicon.function_words).toEqual(baseline.function_words);
  });
});

describe('no grammar change', () => {
  const frozen = [
    'phonology',
    'morphology',
    'motion_prefixes',
    'grammar',
    'function_words',
    'pronouns',
    'correlatives',
    'numbers',
    'time_and_dates',
    'colors',
    'discourse_particles',
    'rulings_1_0',
    'rulings_0_8_carried',
    'legacy',
    'sound_ledger',
    'dispositions',
    'settled_open_questions_0_8',
    'snapshot_0_8',
    'changelog_1_0',
    'rhyme_families',
  ] as const;

  it.each(frozen)('leaves %s byte-identical', (key) => {
    expect((result.lexicon as unknown as Record<string, unknown>)[key]).toEqual(
      (baseline as unknown as Record<string, unknown>)[key],
    );
  });

  it('changes only version, built_utc, source, headwords and examples', () => {
    const changed = Object.keys(baseline).filter(
      (k) =>
        JSON.stringify((baseline as unknown as Record<string, unknown>)[k]) !==
        JSON.stringify((result.lexicon as unknown as Record<string, unknown>)[k]),
    );
    expect(changed.sort()).toEqual(['built_utc', 'examples', 'headwords', 'source', 'version']);
  });

  it('keeps the top-level key set and order', () => {
    expect(Object.keys(result.lexicon)).toEqual(Object.keys(baseline));
  });
});

describe('1.0 is carried verbatim', () => {
  it('keeps all 1099 headwords identical and in order', () => {
    for (const [i, before] of baseline.headwords.entries()) {
      expect(result.lexicon.headwords[i]).toEqual(before);
    }
  });

  it('appends examples without touching the existing 452', () => {
    for (const [i, before] of baseline.examples.entries()) {
      expect(result.lexicon.examples[i]).toEqual(before);
    }
    expect(result.lexicon.examples).toHaveLength(baseline.examples.length + NEW_EXAMPLES.length);
  });
});

describe('new entries', () => {
  it('generate every form from the 1.0 rule, not from the proposal', () => {
    const base = new Set(baseline.headwords.map((h) => h.root));
    for (const h of result.lexicon.headwords) {
      if (base.has(h.root)) continue;
      const expected = sevenForms(h.root);
      const stored = h.forms as unknown as Record<string, string>;
      expect(stored.root).toBe(expected.root);
      expect(stored.verb).toBe(expected.verb);
      expect(stored.ascended).toBe(expected.ascended);
      expect(stored.negative_adjective).toBe(expected.negativeAdjective);
      expect(stored.ascended_adjective).toBe(expected.ascendedAdjective);
    }
  });

  it('carry both status fields and since 1.1', () => {
    const base = new Set(baseline.headwords.map((h) => h.root));
    for (const h of result.lexicon.headwords) {
      if (base.has(h.root)) continue;
      const rec = h as unknown as Record<string, unknown>;
      // status_1_0 keeps the author's unmodified validate.py working (ADR-0009).
      expect(rec.status_1_0).toBe('NEW');
      expect(rec.status_1_1).toBe('NEW');
      expect(rec.since).toBe('1.1');
      expect(rec.protected).toBe(true);
      expect(rec.history_0_8).toBeNull();
    }
  });

  it('carry an editorial trail in notes', () => {
    const base = new Set(baseline.headwords.map((h) => h.root));
    for (const h of result.lexicon.headwords) {
      if (base.has(h.root)) continue;
      expect(h.notes).toMatch(/Added in 1\.1/);
      expect(h.notes.length).toBeGreaterThan(40);
    }
  });

  it('never fill a slot the proposal left unused', () => {
    const base = new Set(baseline.headwords.map((h) => h.root));
    const proposed = new Map(
      [...proposal.root_candidates, ...proposal.compound_candidates].map((c) => [
        c.headword,
        c.proposed_glosses,
      ]),
    );
    for (const h of result.lexicon.headwords) {
      if (base.has(h.root)) continue;
      const want = proposed.get(h.root) as unknown as Record<string, string>;
      const got = h.glosses as unknown as Record<string, string>;
      for (const key of Object.keys(got)) {
        // The root gloss may be narrowed; the other six are taken as proposed.
        if (key === 'root') continue;
        expect(got[key], `${h.root}.${key}`).toBe(want[key]);
      }
    }
  });
});

describe('editorial decisions', () => {
  it('narrows exactly eight glosses, each with a reason', () => {
    const narrowed = result.added.filter((a) => a.outcome === 'narrowed');
    expect(narrowed).toHaveLength(8);
    for (const n of narrowed) {
      expect(n.reason).toBeDefined();
      expect(n.originalGloss).toBeDefined();
      expect(n.gloss).not.toBe(n.originalGloss);
    }
  });

  it('writes each narrowed gloss into the lexicon', () => {
    const byRoot = new Map(result.lexicon.headwords.map((h) => [h.root, h]));
    for (const d of DECISIONS) {
      if (d.kind !== 'narrow' || d.gloss === undefined) continue;
      const h = byRoot.get(d.headword);
      expect(h, d.headword).toBeDefined();
      expect((h?.glosses as unknown as Record<string, string>).root).toBe(d.gloss);
      expect(h?.notes).toMatch(/Gloss narrowed on integration/);
    }
  });

  it('resolves the gloss-versus-scope contradictions it claims to', () => {
    const byRoot = new Map(result.lexicon.headwords.map((h) => [h.root, h]));
    // Each of these said one thing in the gloss and another in the scope.
    expect((byRoot.get('germabiti')?.glosses as unknown as Record<string, string>).root).toMatch(
      /metal/,
    );
    expect(
      (byRoot.get('germabiti')?.glosses as unknown as Record<string, string>).root,
    ).not.toMatch(/steel/);
    expect((byRoot.get('folnitino')?.glosses as unknown as Record<string, string>).root).toMatch(
      /flowering/,
    );
    expect(
      (byRoot.get('lazuralka')?.glosses as unknown as Record<string, string>).root,
    ).not.toMatch(/predator/);
  });

  it('documents nine accepted overlaps', () => {
    expect(ACCEPTED_OVERLAPS).toHaveLength(9);
    for (const o of ACCEPTED_OVERLAPS) expect(o.why.length).toBeGreaterThan(20);
  });

  it('keeps the four dual-analysis -pago compounds, declaring [base, pago]', () => {
    const byRoot = new Map(result.lexicon.headwords.map((h) => [h.root, h]));
    for (const w of DUAL_ANALYSIS_PAGO) {
      const h = byRoot.get(w);
      expect(h, w).toBeDefined();
      expect(h?.components?.[1]).toBe('pago');
      expect(h?.components?.[0]).toBe(w.slice(0, -4));
    }
  });

  it('follows the precedent 1.0 set with larbopago, mavopago and sasvapago', () => {
    const byRoot = new Map(baseline.headwords.map((h) => [h.root, h]));
    for (const w of ['larbopago', 'mavopago', 'sasvapago']) {
      expect(byRoot.get(w)?.components?.[1], w).toBe('pago');
    }
  });
});

describe('derived synonyms', () => {
  it('come from the entry own glosses, never invented', () => {
    const glosses = {
      root: 'animal; living member of the animal kingdom',
      ascended: '— (unused)',
      negative: '— (unused)',
      verb: '— (unused)',
      negative_adjective: '— (unused)',
      adjective: 'animal; zoological',
      ascended_adjective: '— (unused)',
    } as unknown as RawSlots;
    expect(deriveSynonyms(glosses)).toEqual([
      'animal',
      'living member of the animal kingdom',
      'zoological',
    ]);
  });

  it('drop the unused marker and never emit an empty string', () => {
    const base = new Set(baseline.headwords.map((h) => h.root));
    for (const h of result.lexicon.headwords) {
      if (base.has(h.root)) continue;
      const synonyms = h.english_synonyms as string[];
      expect(synonyms.length).toBeGreaterThan(0);
      for (const s of synonyms) {
        expect(s.trim()).not.toBe('');
        expect(s).not.toContain('—');
      }
    }
  });
});

describe('the independent audit', () => {
  it('passes every check', () => {
    const report = auditIntegration(baseline, result.lexicon);
    expect(report.findings).toEqual([]);
    expect(report.passed).toBe(true);
    expect(report.clean.length).toBeGreaterThanOrEqual(17);
  });

  it('would catch a tampered 1.0 entry', () => {
    const tampered = JSON.parse(JSON.stringify(result.lexicon)) as RawLexicon;
    const first = tampered.headwords[0];
    if (first !== undefined) first.register = 'poetic';
    const report = auditIntegration(baseline, tampered);
    expect(report.passed).toBe(false);
    expect(report.findings.some((f) => f.check.includes('1.0 headwords unchanged'))).toBe(true);
  });

  it('would catch a changed grammar section', () => {
    const tampered = JSON.parse(JSON.stringify(result.lexicon)) as RawLexicon;
    tampered.grammar.clause_template = 'SUBJ VERB OBJ';
    const report = auditIntegration(baseline, tampered);
    expect(report.passed).toBe(false);
    expect(report.findings.some((f) => f.detail.includes('grammar changed'))).toBe(true);
  });

  it('would catch a form that does not follow the verb rule', () => {
    const tampered = JSON.parse(JSON.stringify(result.lexicon)) as RawLexicon;
    const added = tampered.headwords[1200];
    if (added !== undefined) {
      (added.forms as unknown as Record<string, string>).verb = 'wrongform';
    }
    const report = auditIntegration(baseline, tampered);
    expect(report.passed).toBe(false);
  });
});

describe('new examples', () => {
  it('number at least the 120 required, across five domains', () => {
    expect(NEW_EXAMPLES.length).toBeGreaterThanOrEqual(120);
    const domains = new Set(NEW_EXAMPLES.map((e) => e.domain));
    expect([...domains].sort()).toEqual([
      'everyday',
      'natural world',
      'philosophical',
      'social',
      'technological',
    ]);
  });

  it('give every domain a real share', () => {
    const counts = new Map<string, number>();
    for (const e of NEW_EXAMPLES) counts.set(e.domain, (counts.get(e.domain) ?? 0) + 1);
    for (const [, n] of counts) expect(n).toBeGreaterThanOrEqual(20);
  });

  it('use each of the 21 new roots at least twice', () => {
    const newRoots = proposal.root_candidates.map((r) => r.headword);
    const byRoot = new Map(result.lexicon.headwords.map((h) => [h.root, h]));

    /** Every primal root a spelling is built from, following nesting. */
    const primalsOf = (word: string, seen = new Set<string>()): Set<string> => {
      if (seen.has(word)) return new Set();
      const h = byRoot.get(word);
      if (h?.components === null || h?.components === undefined) return new Set([word]);
      const out = new Set<string>();
      for (const c of h.components) {
        for (const p of primalsOf(c, new Set([...seen, word]))) out.add(p);
      }
      return out;
    };

    // Index every form of every headword back to its entry.
    const formToRoot = new Map<string, string>();
    for (const h of result.lexicon.headwords) {
      for (const f of Object.values(h.forms as unknown as Record<string, string>)) {
        formToRoot.set(f, h.root);
      }
    }

    const uses = new Map<string, number>();
    for (const e of NEW_EXAMPLES) {
      const hit = new Set<string>();
      for (const raw of e.liraasa.toLowerCase().split(/[^a-z-]+/)) {
        const token = raw.replace(/^-+|-+$/g, '');
        if (token.length === 0) continue;
        const root =
          formToRoot.get(token) ??
          (token.endsWith('ri') ? formToRoot.get(token.slice(0, -2)) : undefined);
        if (root === undefined) continue;
        for (const p of primalsOf(root)) hit.add(p);
      }
      for (const r of hit) {
        if (newRoots.includes(r)) uses.set(r, (uses.get(r) ?? 0) + 1);
      }
    }

    const short = newRoots.filter((r) => (uses.get(r) ?? 0) < 2);
    expect(short).toEqual([]);
  });

  it('shape each row like a 1.0 example, with no changes key', () => {
    const base = baseline.examples.length;
    for (let i = base; i < result.lexicon.examples.length; i += 1) {
      const e = result.lexicon.examples[i] as unknown as Record<string, unknown>;
      expect(Object.keys(e).sort()).toEqual(['english', 'feature', 'liraasa', 'source', 'status']);
      expect(e.status).toBe('NEW');
    }
  });
});

describe('determinism', () => {
  it('produces identical output from identical input', () => {
    const again = integrate(freshRawLexicon(), proposal, {
      version: '1.1',
      builtUtc: '2026-10-16T12:00:00Z',
      baselineSha256: BASELINE_SHA,
      newExamples: NEW_EXAMPLES.map((e) => ({
        liraasa: e.liraasa,
        english: e.english,
        feature: e.feature,
        status: 'NEW',
        source: `1.1 vocabulary examples (${e.domain})`,
      })),
    });
    expect(JSON.stringify(again.lexicon)).toBe(JSON.stringify(result.lexicon));
  });
});
